package snapshot
type Store struct{items []string}
func(s *Store)Add(v string){s.items=append(s.items,v)}
func(s *Store)Snapshot()[]string{return s.items}

package snapshot
import"testing"
func TestSnapshotIsStable(t *testing.T){var s Store;s.Add("a");snap:=s.Snapshot();s.Add("b");if len(snap)!=1||snap[0]!="a"{t.Fatal(snap)}}

package snapshot
import"testing"
func TestCallerCannotMutateStore(t *testing.T){var s Store;s.Add("a");x:=s.Snapshot();x[0]="changed";if s.Snapshot()[0]!="a"{t.Fatal("aliased")}}

